{
  "key": "msme.health_{{$timestamp}}",
  "name": {
    "en": "Scoring Model"
  },
  "content": {
    "scope": {
      "segments": [
        "msme"
      ]
    },
    "attentionBelowPct": 60,
    "bands": [
      {
        "min": 0,
        "label": {
          "en": "Needs Work Before Matching"
        }
      },
      {
        "min": 40,
        "label": {
          "en": "Fair — A Few Gaps To Close"
        }
      },
      {
        "min": 60,
        "label": {
          "en": "Good — Ready For Funding"
        }
      },
      {
        "min": 80,
        "label": {
          "en": "Strong — Ready For Funding"
        }
      }
    ],
    "factors": [
      {
        "key": "vintage",
        "label": {
          "en": "Business Vintage"
        },
        "max": 10,
        "method": "linear",
        "linear": {
          "attr": "business.vintage_months",
          "from": 0,
          "to": 60
        }
      },
      {
        "key": "turnover",
        "label": {
          "en": "Profitability & Margins"
        },
        "max": 20,
        "method": "bands",
        "missing": "zero",
        "bands": [
          {
            "when": {
              "attr": "business.monthly_turnover_paise",
              "op": "gte",
              "value": 250000000
            },
            "points": 20
          },
          {
            "when": {
              "attr": "business.monthly_turnover_paise",
              "op": "gte",
              "value": 50000000
            },
            "points": 12
          }
        ]
      },
      {
        "key": "gst",
        "label": {
          "en": "GST & ITR Consistency"
        },
        "max": 15,
        "method": "bands",
        "missing": "zero",
        "bands": [
          {
            "when": {
              "attr": "business.gst_registered",
              "op": "eq",
              "value": true
            },
            "points": 15
          }
        ]
      }
    ]
  }
}

